#!/usr/bin/env node
/**
 * Copies the CV files generated by Python (cv/output) into apps/web/public/cv,
 * so the web always serves the same files you have locally.
 * Runs before `pnpm dev` and `pnpm build` of @mportafolio/web.
 */
import { copyFileSync, existsSync, mkdirSync, readdirSync, rmSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '..', '..')
const source = join(repoRoot, 'cv', 'output')
const target = join(repoRoot, 'apps', 'web', 'public', 'cv')

if (!existsSync(source)) {
  console.error(`[sync-cv] Missing ${source}. Run \`pnpm cv:generate\` first.`)
  process.exit(1)
}

const files = readdirSync(source).filter((name) => /\.(pdf|docx)$/i.test(name))
if (files.length === 0) {
  console.error('[sync-cv] cv/output has no PDF/DOCX files. Run `pnpm cv:generate` first.')
  process.exit(1)
}

rmSync(target, { recursive: true, force: true })
mkdirSync(target, { recursive: true })
for (const name of files) copyFileSync(join(source, name), join(target, name))
console.log(`[sync-cv] ${files.length} CV files copied cv/output -> apps/web/public/cv`)
